WITH inserted AS (
  INSERT INTO public.parqueadero_usuarios(
    tipo_usuario,estudiante_id,docente_id,cedula_manual,nombres_manual,correo_manual,estado
  )
  SELECT 'INVITADO',NULL,NULL,$2,$3,$4,'ACTIVO'
  WHERE NOT EXISTS (
    SELECT 1 FROM public.parqueadero_usuarios
    WHERE tipo_usuario='INVITADO' AND (cedula_manual=$2 OR lower(correo_manual)=lower($4))
  )
  RETURNING id
)
SELECT TRUE AS success,id::int AS id FROM inserted;
